INSERT INTO question_bank (question_text, options, correct_option, topic, difficulty, is_active) VALUES
('Which OOP principle refers to the bundling of data and methods that operate on that data within a single unit?', '["Inheritance", "Encapsulation", "Polymorphism", "Abstraction"]'::jsonb, 1, 'oop', 'easy', true),
('What is the primary purpose of abstraction in object-oriented programming?', '["To hide implementation details and expose only essential features", "To allow a class to inherit from multiple classes", "To bind data and methods together into a single unit", "To enable a single method name to behave differently for different inputs"]'::jsonb, 0, 'oop', 'easy', true),
('Which access modifier restricts a class member so that it is accessible only within the same class?', '["public", "protected", "private", "internal"]'::jsonb, 2, 'oop', 'easy', true),
('In OOP, a class is best described as:', '["A blueprint or template for creating objects", "An instance of an object", "A runtime memory allocation", "A special type of function"]'::jsonb, 0, 'oop', 'easy', true),
('An object in object-oriented programming is:', '["A syntax rule for defining functions", "An instance of a class", "A type of loop construct", "A file containing source code"]'::jsonb, 1, 'oop', 'easy', true),
('Which OOP pillar allows a child class to acquire the properties and behaviors of a parent class?', '["Encapsulation", "Abstraction", "Inheritance", "Polymorphism"]'::jsonb, 2, 'oop', 'easy', true),
('Which term describes the ability of objects of different classes to be treated through a common interface, each providing its own behavior?', '["Polymorphism", "Encapsulation", "Composition", "Aggregation"]'::jsonb, 0, 'oop', 'easy', true),
('Getter and setter methods are commonly used to support which OOP principle?', '["Inheritance", "Encapsulation", "Polymorphism", "Abstraction"]'::jsonb, 1, 'oop', 'easy', true),
('Which of the following best defines a constructor?', '["A special method automatically invoked to initialize an object when it is created", "A method that destroys an object when it is no longer needed", "A method that can only be called explicitly by the programmer, never automatically", "A static utility method with no relation to object creation"]'::jsonb, 0, 'oop', 'easy', true),
('What is the main role of a destructor in a class?', '["To release resources and perform cleanup before an object is destroyed", "To initialize member variables when an object is created", "To overload the class''s other methods", "To create a new object from an existing one"]'::jsonb, 0, 'oop', 'easy', true),
('A class exposes only a small set of well-defined public methods while keeping its internal state private. This design choice is primarily an example of information hiding, a key aspect of:', '["Encapsulation", "Multiple inheritance", "Method overloading", "Dynamic binding"]'::jsonb, 0, 'oop', 'medium', true),
('Which statement correctly distinguishes abstraction from encapsulation?', '["Abstraction hides complexity by exposing only relevant functionality, while encapsulation hides data by restricting direct access to it", "Abstraction restricts access to variables, while encapsulation hides implementation complexity", "Abstraction and encapsulation are identical concepts with different names", "Encapsulation is achieved only through inheritance, while abstraction is achieved only through interfaces"]'::jsonb, 0, 'oop', 'medium', true),
('A bank account class stores the balance as a private field and only allows modification through deposit() and withdraw() methods that validate the amount. Which principle is most directly illustrated?', '["Encapsulation", "Multiple inheritance", "Method overloading", "Dynamic binding"]'::jsonb, 0, 'oop', 'medium', true),
('Declaring a class member as ''protected'' typically means it is accessible:', '["Within the same class and its subclasses (and often the same package)", "From anywhere in the program without restriction", "Only within the single method where it is declared", "Only by static methods of unrelated classes"]'::jsonb, 0, 'oop', 'medium', true),
('Which of these is NOT typically considered one of the four pillars of OOP?', '["Encapsulation", "Iteration", "Abstraction", "Polymorphism"]'::jsonb, 1, 'oop', 'medium', true),
('An abstract class in most OOP languages:', '["Cannot be instantiated directly and may contain both implemented and unimplemented methods", "Must fully implement every method it declares", "Can never contain a constructor", "Can only be used as a marker with no members at all"]'::jsonb, 0, 'oop', 'medium', true),
('Why might a class provide a public getter method for a private field instead of making the field public directly?', '["To control and validate access to the field while hiding its internal representation", "To increase the memory used by each object", "To force the class to become abstract", "To enable the class to support multiple inheritance"]'::jsonb, 0, 'oop', 'medium', true),
('Which scenario best demonstrates abstraction rather than plain encapsulation?', '["A remote control exposes simple buttons like ''power'' and ''volume'' without revealing the internal circuitry", "A class marks all of its fields as private", "A class provides only getter methods and no setters", "A class places all of its code in a single source file"]'::jsonb, 0, 'oop', 'medium', true),
('Which of the following is an example of loose coupling achieved through abstraction?', '["A class depends on an interface type rather than a concrete implementation class", "A class directly instantiates and calls methods on a specific concrete class it depends on", "A class copies another class''s private fields into its own fields", "A class inherits directly from three different concrete base classes"]'::jsonb, 0, 'oop', 'medium', true),
('What does the ''is-a'' relationship typically represent in OOP?', '["Inheritance, where a subclass is a specialized type of its superclass", "Composition, where one class contains another as a member", "Aggregation, where objects share a weak ownership relationship", "Association, where two unrelated classes interact temporarily"]'::jsonb, 0, 'oop', 'medium', true),
('A class can switch its internal data structure from an array to a linked list without changing its public API or affecting any client code. This most directly demonstrates:', '["Encapsulation, since implementation details are hidden behind a stable interface", "Inheritance, since the subclass overrides the data structure", "Polymorphism, since the same method name behaves differently for different types", "Aggregation, since the class contains a reference to another object"]'::jsonb, 0, 'oop', 'hard', true),
('Which is the most accurate relationship between abstraction and encapsulation?', '["Abstraction is a design-level concept about what to expose, while encapsulation is an implementation-level mechanism (such as access modifiers) used to enforce it", "They are unrelated concepts that are never used together in practice", "Encapsulation is a subtype of inheritance in every OOP language", "Abstraction can only be achieved using abstract classes, never through interfaces"]'::jsonb, 0, 'oop', 'hard', true),
('A destructor-like mechanism in a language with automatic garbage collection (such as Java) is generally:', '["Not guaranteed to run at a predictable time, since such languages rely on garbage collection rather than deterministic destructors", "Called immediately when an object goes out of scope, just like in C++", "Required for every class in order to avoid memory leaks", "The only reliable way to release file handles or network connections"]'::jsonb, 0, 'oop', 'hard', true),
('Which best explains why constructors are generally not treated as overridable in the same polymorphic sense as ordinary virtual methods?', '["At the moment a constructor executes, the object''s concrete type is already fixed by the creation expression, so dynamic dispatch through a virtual mechanism is unnecessary for selecting which constructor runs", "Because constructors do not exist in compiled languages", "Because all constructors are private by default in every OOP language", "Because constructors always return a value and virtual methods cannot return values"]'::jsonb, 0, 'oop', 'hard', true),
('A class declares a private constructor and exposes a public static method to obtain its single shared instance. Which principle best explains why the constructor is made private?', '["Encapsulation restricts direct instantiation so the class can enforce an invariant, such as allowing only one instance, as in the Singleton pattern", "Abstraction requires that all constructors in every class be private", "Every class that implements an interface is required to have a private constructor", "Private constructors are only needed for classes declared abstract"]'::jsonb, 0, 'oop', 'hard', true);
INSERT INTO question_bank (question_text, options, correct_option, topic, difficulty, is_active) VALUES
('Which type of inheritance involves a class inheriting directly from more than one base class?', '["Single inheritance", "Multiple inheritance", "Hierarchical inheritance", "Multilevel inheritance"]'::jsonb, 1, 'oop', 'easy', true),
('In hierarchical inheritance:', '["Multiple derived classes inherit from a single base class", "A single derived class inherits from multiple base classes", "A class inherits from a class that itself inherits from another class", "A class inherits from itself"]'::jsonb, 0, 'oop', 'easy', true),
('Method overloading is primarily an example of which type of polymorphism?', '["Compile-time (static) polymorphism", "Run-time (dynamic) polymorphism", "Structural polymorphism only", "Coercion-only polymorphism"]'::jsonb, 0, 'oop', 'easy', true),
('Method overriding is primarily an example of which type of polymorphism?', '["Compile-time (static) polymorphism", "Run-time (dynamic) polymorphism", "Ad-hoc polymorphism only", "Parametric polymorphism only"]'::jsonb, 1, 'oop', 'easy', true),
('Which annotation is commonly used in Java to indicate that a subclass method is intended to override a superclass method?', '["@Override", "@Overload", "@Static", "@Virtual"]'::jsonb, 0, 'oop', 'easy', true),
('What does the ''super'' keyword typically refer to when used inside a subclass?', '["The immediate parent class", "The current object itself", "A static utility class", "An interface implemented by the class"]'::jsonb, 0, 'oop', 'easy', true),
('Which of the following is required for true method overriding to occur between a superclass and a subclass?', '["The method must have the same name, the same parameters, and be inherited by the subclass", "The methods must have the same name but different parameter lists", "The methods must both be declared static", "The methods must be defined in two completely unrelated classes"]'::jsonb, 0, 'oop', 'easy', true),
('In method overloading, which of the following must differ between the overloaded methods?', '["The parameter list (number, type, or order of parameters)", "The return type only, with identical parameters", "The method''s access modifier only", "Nothing; overloaded methods must be entirely identical"]'::jsonb, 0, 'oop', 'easy', true),
('Which OOP concept allows a single method name to behave differently depending on the object or arguments it is invoked with?', '["Polymorphism", "Inheritance", "Encapsulation", "Instantiation"]'::jsonb, 0, 'oop', 'easy', true),
('A subclass attempts to extend a class marked ''final'' (as in Java). What happens?', '["Compilation fails, because final classes cannot be inherited", "The subclass inherits normally with no restriction", "The subclass automatically becomes abstract", "The subclass overrides all parent methods by default"]'::jsonb, 0, 'oop', 'easy', true),
('Given a superclass reference variable pointing to a subclass object, calling an overridden method invokes:', '["The subclass''s overridden version, determined at runtime", "The superclass''s version, determined at compile time", "Neither version; this always causes a compiler error", "Both versions, executed one after another"]'::jsonb, 0, 'oop', 'medium', true),
('Why is multiple inheritance of implementation considered problematic in many OOP languages, leading to issues like the ''diamond problem''?', '["Ambiguity can arise when two parent classes define the same member, making it unclear which version the subclass should inherit", "It makes every program run out of memory immediately", "It is technically impossible for any language to implement", "It always causes an infinite loop at runtime"]'::jsonb, 0, 'oop', 'medium', true),
('How does Java provide flexibility similar to multiple inheritance while avoiding true multiple class inheritance?', '["By allowing a class to implement multiple interfaces", "By allowing a class to declare multiple constructors only", "By requiring all classes to be declared abstract", "By disallowing inheritance altogether"]'::jsonb, 0, 'oop', 'medium', true),
('A parent class method returns type ''Animal'', and an overriding subclass method returns type ''Dog'' (a subtype of Animal). This is an example of:', '["Covariant return types, which are permitted when overriding", "Invalid overriding that will always fail to compile", "Method overloading rather than overriding", "Contravariant parameter typing"]'::jsonb, 0, 'oop', 'medium', true),
('Which statement about constructors and inheritance is true?', '["A subclass constructor implicitly or explicitly calls a superclass constructor before executing its own body", "Constructors are inherited directly by subclasses just like normal methods", "A subclass can never call any constructor of its superclass", "Superclass constructors are always inaccessible to subclasses"]'::jsonb, 0, 'oop', 'medium', true),
('What is ''method hiding'' in the context of static methods within an inheritance hierarchy (e.g., in Java)?', '["When a subclass defines a static method with the same signature as one in the superclass, and resolution is based on the reference type rather than the object type", "The same phenomenon as overriding, always resolved dynamically at runtime", "A compiler error that always occurs when static methods share a name", "A technique used to make private methods visible to subclasses"]'::jsonb, 0, 'oop', 'medium', true),
('Which of the following best demonstrates compile-time polymorphism aside from ordinary method overloading?', '["Operator overloading, where the same operator behaves differently based on operand types", "Overriding a virtual method in a subclass", "Late binding through a virtual method table", "Implementing an interface and choosing the implementation at runtime"]'::jsonb, 0, 'oop', 'medium', true),
('In multilevel inheritance, if class C extends class B, and class B extends class A, which statement is true?', '["C inherits members from both B and A, forming a chain", "C can access members of B only, never those of A", "A automatically inherits members from C", "This is not a valid inheritance structure in OOP"]'::jsonb, 0, 'oop', 'medium', true),
('Which best explains why a subclass overrides a method inherited from an abstract superclass?', '["It provides a concrete implementation to complete a method the abstract superclass left unimplemented", "It hides a static method that cannot be inherited", "It aggregates the abstract method into a separate helper class", "It converts the abstract method into a private one"]'::jsonb, 0, 'oop', 'medium', true),
('Which relationship does inheritance primarily model between two classes?', '["An ''is-a'' relationship where the subclass is a specialized kind of the superclass", "A ''has-a'' relationship where one class contains another", "A ''uses-a'' relationship representing a temporary interaction", "A ''creates-a'' relationship representing object instantiation only"]'::jsonb, 0, 'oop', 'medium', true),
('Can a subclass override a private method declared in its superclass?', '["No, private methods are not inherited or visible to subclasses, so a same-signature subclass method is a new, unrelated method rather than an override", "Yes, private methods are always overridden exactly like public methods", "Yes, but only if the subclass is declared in the same source file", "No, because declaring a private method in a superclass causes a compile error"]'::jsonb, 0, 'oop', 'hard', true),
('Why can dynamic dispatch still route to a subclass''s overridden method even when that method is called from within the base class''s own constructor, in languages such as Java?', '["Because virtual dispatch still resolves to the runtime type during base construction, even though the subclass''s own fields may not yet be initialized, which is a common source of subtle bugs", "Because subclass fields are always guaranteed to be initialized before the base constructor runs", "Because virtual dispatch is completely disabled during any constructor call in Java", "Because constructors in Java are resolved purely at compile time with no runtime component"]'::jsonb, 0, 'oop', 'hard', true),
('In C++, if a base class destructor is not declared ''virtual'', what happens when a derived object is deleted through a base class pointer?', '["Only the base class destructor runs, which can leave derived-class resources unreleased and cause undefined behavior", "Both destructors always run correctly regardless of the virtual keyword", "The program fails to compile", "The derived class destructor runs first, followed by the base class destructor"]'::jsonb, 0, 'oop', 'hard', true),
('Which best distinguishes ''overload resolution'' from ''dynamic dispatch''?', '["Overload resolution selects among overloaded methods at compile time based on static argument types, while dynamic dispatch selects the actual implementation at runtime based on the object''s actual type", "They are two names for exactly the same runtime mechanism", "Overload resolution happens at runtime, while dynamic dispatch happens at compile time", "Both always resolve to the base class''s implementation regardless of context"]'::jsonb, 0, 'oop', 'hard', true),
('A subclass overrides a method but declares a broader (more permissive) access modifier than the superclass version, for example changing protected to public. Is this generally allowed?', '["Yes, most OOP languages allow widening access in an override but not narrowing it, since narrowing would violate the superclass''s contract", "No, the access modifier must always match exactly between override and superclass method", "Yes, but only if the method is also declared static", "No, overriding a method never permits any change to its access modifier"]'::jsonb, 0, 'oop', 'hard', true);
INSERT INTO question_bank (question_text, options, correct_option, topic, difficulty, is_active) VALUES
('What is stored separately when multiple objects are created from the same class?', '["Each object has its own copy of instance variables, but they share the same method definitions", "Each object shares the exact same memory for its instance variables", "Each object gets a separate copy of the class''s method code in memory", "Objects of the same class are not permitted to have different attribute values"]'::jsonb, 0, 'oop', 'easy', true),
('A default constructor is:', '["A constructor with no parameters, often provided automatically by the compiler if no other constructor is defined", "A constructor that always takes exactly one parameter", "A constructor that can never be invoked explicitly by the programmer", "A method used only to destroy objects"]'::jsonb, 0, 'oop', 'easy', true),
('What is a parameterized constructor used for?', '["To initialize an object''s fields with specific values passed as arguments at creation time", "To destroy an object using specific parameters", "To override a method with additional parameters", "To declare an interface with default parameter values"]'::jsonb, 0, 'oop', 'easy', true),
('In Java, what is the name of the special member that shares the class''s name, has no return type, and is used to initialize new objects?', '["Constructor", "Destructor", "Finalizer", "Accessor"]'::jsonb, 0, 'oop', 'easy', true),
('Which of these is traditionally true about an interface in statically typed OOP languages (for example, Java before version 8)?', '["It declares method signatures without implementations, and implementing classes must define those methods", "It can contain fully implemented methods but is not allowed to declare any fields at all", "It can be instantiated directly, just like a regular class", "It replaces the need for classes entirely in the language"]'::jsonb, 0, 'oop', 'easy', true),
('Can an abstract class have a constructor?', '["Yes, and it runs when a subclass object is instantiated, even though the abstract class itself cannot be instantiated directly", "No, abstract classes can never define a constructor", "Yes, but it can never initialize any of the class''s fields", "No, because abstract classes occupy no memory at all"]'::jsonb, 0, 'oop', 'easy', true),
('Which of the following can a class do with interfaces in languages like Java?', '["Implement multiple interfaces simultaneously", "Implement at most one interface at a time", "Never implement any interface under any circumstance", "Implement interfaces only if the class itself is abstract"]'::jsonb, 0, 'oop', 'easy', true),
('A copy constructor is used to:', '["Create a new object as a copy of an existing object of the same class", "Delete an existing object from memory", "Convert one class''s object into an object of a completely unrelated type", "Compare two objects for equality"]'::jsonb, 0, 'oop', 'easy', true),
('Which of the following is true about static (class-level) members?', '["They belong to the class itself rather than to any individual object, and are shared across all instances", "They belong exclusively to a single object instance", "They cannot be accessed without first creating an object", "They are recreated separately for every method call"]'::jsonb, 0, 'oop', 'easy', true),
('What does UML stand for?', '["Unified Modeling Language", "Universal Machine Language", "Unified Method Library", "User Modeling Layout"]'::jsonb, 0, 'oop', 'easy', true),
('Which best distinguishes an interface from an abstract class in a language that supports both, such as Java?', '["A class can implement multiple interfaces but typically extend only one abstract class", "An interface can define constructors while an abstract class cannot", "An abstract class cannot contain any abstract methods, while an interface always can", "Interfaces support mutable instance fields with state, while abstract classes cannot have fields"]'::jsonb, 0, 'oop', 'medium', true),
('When should a language designer or developer generally prefer an interface over an abstract class?', '["When defining a contract that unrelated classes can implement, without forcing a shared inheritance hierarchy", "When needing to share common field state and a default constructor across classes", "When no implementation flexibility should ever be allowed", "When the classes must all belong to the exact same inheritance chain"]'::jsonb, 0, 'oop', 'medium', true),
('Modern languages such as Java (version 8+) allow interfaces to declare ''default methods''. What is the primary purpose of this feature?', '["To let an interface provide a default implementation so existing implementing classes are not broken when new methods are added", "To allow interfaces to be instantiated directly like concrete classes", "To eliminate the need for abstract classes in every possible case", "To make all interface methods static by default"]'::jsonb, 0, 'oop', 'medium', true),
('Which UML notation represents an ''is-a'' (generalization/inheritance) relationship between two classes?', '["A solid line with a hollow (unfilled) triangular arrowhead pointing to the superclass", "A dashed line with an open arrowhead", "A solid line with a filled diamond", "A solid line with a filled arrowhead"]'::jsonb, 0, 'oop', 'medium', true),
('In a UML class diagram, what does a filled (solid) diamond at one end of an association line typically represent?', '["Composition, a strong ''part-of'' relationship where the part cannot exist independently of the whole", "Aggregation, a weak ownership relationship", "Inheritance, a generalization relationship", "Dependency, a temporary usage relationship"]'::jsonb, 0, 'oop', 'medium', true),
('In a UML class diagram, what does a hollow (unfilled) diamond typically represent?', '["Aggregation, a ''has-a'' relationship where the part can exist independently of the whole", "Composition, where the part cannot exist without the whole", "Realization, where a class implements an interface", "Multiplicity, indicating how many objects participate"]'::jsonb, 0, 'oop', 'medium', true),
('What is the key difference between aggregation and composition?', '["In composition, the contained object''s lifetime is bound to the container; in aggregation, the contained object can exist independently", "Aggregation always relies on inheritance, while composition never does", "Composition allows multiple containers to share the same part, while aggregation forbids sharing", "There is no real difference; the two terms are fully interchangeable"]'::jsonb, 0, 'oop', 'medium', true),
('Which symbol in a UML class diagram denotes a ''realization'' relationship, such as a class implementing an interface?', '["A dashed line with a hollow triangular arrowhead", "A solid line with a hollow triangular arrowhead", "A solid line with a filled diamond", "A dashed line with a filled arrowhead"]'::jsonb, 0, 'oop', 'medium', true),
('Why can''t you instantiate an interface directly, even though you can declare a variable of the interface type?', '["An interface traditionally lacks concrete method implementations, so there is no complete behavior from which to construct an object", "Interfaces are not real types in any programming language", "Interfaces automatically instantiate as null objects at runtime", "Interfaces can only be referenced from inside abstract classes"]'::jsonb, 0, 'oop', 'medium', true),
('A class diagram shows Car and Engine connected by a composition relationship, with the filled diamond on the Car side. What does this imply?', '["If a Car object is destroyed, its associated Engine object is also destroyed, since the Engine cannot meaningfully exist without its owning Car", "The Engine object can be freely shared between multiple Car objects", "Car inherits all of its methods directly from Engine", "Engine and Car have no real relationship beyond a shared naming convention"]'::jsonb, 0, 'oop', 'medium', true),
('Which is a valid reason to design a type as an abstract class rather than an interface, in a language supporting both?', '["The type needs to share common state (fields) and provide partial, reusable implementation logic across related subclasses", "The type must be implemented by classes drawn from entirely unrelated hierarchies", "The type should never provide any method bodies at all", "The type must support being combined with several other supertypes simultaneously"]'::jsonb, 0, 'oop', 'hard', true),
('In a language without multiple class inheritance, why might interfaces with default methods still not fully replace abstract classes?', '["Interfaces, even with default methods, generally cannot declare instance fields to hold shared mutable state, which abstract classes can", "Interfaces cannot declare any methods at all, even with the default keyword", "Default methods in interfaces are always private and therefore useless", "Interfaces cannot be implemented by more than one class at a time"]'::jsonb, 0, 'oop', 'hard', true),
('What does constructor chaining (one constructor calling another constructor within the same class) accomplish?', '["It allows one constructor to reuse initialization logic defined in another constructor of the same class, reducing code duplication", "It refers to calling constructors of several unrelated classes in sequence", "It is mandatory for every class, regardless of how many constructors it defines", "It automatically creates a new subclass at runtime"]'::jsonb, 0, 'oop', 'hard', true),
('If a class defines no constructor at all, and its superclass provides only a parameterized constructor (no no-argument constructor), what happens?', '["Compilation fails, because the implicit default constructor of the subclass cannot find a matching no-argument constructor to call in the superclass", "The subclass automatically inherits the parameterized constructor as its own default constructor", "The program compiles and runs fine, using null for every field", "The superclass automatically gains an implicit no-argument constructor"]'::jsonb, 0, 'oop', 'hard', true),
('Why is it generally considered bad practice to call an overridable (virtual) method from within a constructor?', '["If a subclass overrides that method, it may be invoked before the subclass''s own fields are fully initialized, leading to inconsistent object state", "Because constructors are not permitted to call any methods whatsoever", "Because doing so always causes an infinite recursive loop", "Because overridable methods are never compiled when referenced inside constructors"]'::jsonb, 0, 'oop', 'hard', true);
INSERT INTO question_bank (question_text, options, correct_option, topic, difficulty, is_active) VALUES
('Which phrase best captures a ''has-a'' relationship between two classes?', '["Composition, where one class contains an instance of another as a member", "Inheritance, where a subclass extends a superclass", "Overloading, where methods share the same name", "Overriding, where a subclass redefines inherited behavior"]'::jsonb, 0, 'oop', 'easy', true),
('In composition, how does the containing class typically use the contained object''s functionality?', '["By holding a reference to the contained object and delegating calls to it", "By directly inheriting all of its methods", "By overriding all of its methods", "By declaring the contained object as an interface"]'::jsonb, 0, 'oop', 'easy', true),
('Which of the following is an example of composition?', '["A Car class that contains an Engine object as a member field", "A SportsCar class that extends a Car class", "A class that merely implements a Drivable interface", "A method that is overloaded based on its parameter count"]'::jsonb, 0, 'oop', 'easy', true),
('High cohesion in a class generally means:', '["The class''s responsibilities are closely related and focused on a single, well-defined purpose", "The class depends heavily on many unrelated other classes", "The class contains as many unrelated methods as possible", "The class exposes its private fields to every other class"]'::jsonb, 0, 'oop', 'easy', true),
('Low coupling between classes generally means:', '["Classes have minimal dependence on each other''s internal details, making them easier to change independently", "Classes are tightly interconnected and share internal state directly", "Classes are forbidden from communicating with one another at all", "Classes must always inherit from a common base class"]'::jsonb, 0, 'oop', 'easy', true),
('Which design goal is generally preferred in good object-oriented design?', '["High cohesion and low coupling", "Low cohesion and high coupling", "High cohesion and high coupling", "Low cohesion and low coupling"]'::jsonb, 0, 'oop', 'easy', true),
('The design guideline ''favor composition over inheritance'' suggests that:', '["Designers should generally prefer building functionality by combining objects rather than through deep inheritance hierarchies, when either approach would work", "Inheritance should never be used under any circumstances", "Composition and inheritance can never coexist within the same design", "Interfaces should always be avoided in favor of composition"]'::jsonb, 0, 'oop', 'easy', true),
('Which of these best describes aggregation as opposed to composition?', '["Aggregation represents a weaker relationship where the contained object''s lifecycle is independent of the container", "Aggregation always destroys the contained object along with the container", "Aggregation is inherently a stronger relationship than composition", "Aggregation requires the use of multiple inheritance"]'::jsonb, 0, 'oop', 'easy', true),
('A Department class holds a list of Employee objects that continue to exist even if the Department object is removed. This best illustrates:', '["Aggregation", "Composition", "Inheritance", "Overriding"]'::jsonb, 0, 'oop', 'easy', true),
('Which term describes the degree to which the elements inside a single class or module logically belong together?', '["Cohesion", "Coupling", "Inheritance", "Polymorphism"]'::jsonb, 0, 'oop', 'easy', true),
('Why is inheritance sometimes described as creating tighter coupling between a subclass and its superclass compared to composition?', '["Changes to the superclass''s implementation can unexpectedly break subclass behavior, since the subclass depends on more than just the superclass''s public contract", "Subclasses are technically unable to access any superclass methods", "Inheritance always requires implementing an additional interface", "Subclasses must be declared in the exact same source file as their superclass"]'::jsonb, 0, 'oop', 'medium', true),
('Which of the following is a key advantage of composition over inheritance for code reuse?', '["Composition allows behavior to be changed at runtime by swapping the composed object, offering more flexibility than a fixed inheritance hierarchy", "Composition always requires strictly less code than inheritance in every case", "Composition automatically provides polymorphism without needing any interfaces", "Composition eliminates the need for access modifiers entirely"]'::jsonb, 0, 'oop', 'medium', true),
('A class with unrelated methods such as calculateSalary(), sendEmail(), and generateReport() bundled together, with no clear common purpose, exhibits:', '["Low cohesion", "High cohesion", "Low coupling", "Strong encapsulation"]'::jsonb, 0, 'oop', 'medium', true),
('Which scenario best demonstrates tight coupling between two classes?', '["Class A directly accesses and manipulates the internal implementation details of Class B, relying on B''s specific representation", "Class A calls a well-documented public method on an interface implemented by Class B", "Class A and Class B never interact with each other at all", "Class A receives an interface reference to Class B through dependency injection"]'::jsonb, 0, 'oop', 'medium', true),
('Dependency injection is a technique primarily used to:', '["Reduce coupling by supplying a class''s dependencies from outside rather than having the class create them internally", "Increase coupling by hardcoding a class''s dependencies", "Replace the need for interfaces entirely", "Force every class to use multiple inheritance"]'::jsonb, 0, 'oop', 'medium', true),
('Which of the following best reflects the Liskov Substitution Principle in relation to inheritance misuse?', '["If a subclass cannot be substituted for its superclass without breaking expected behavior, the inheritance relationship is likely a design flaw", "Subclasses must always add brand-new methods beyond those in the superclass", "Every class must inherit from at least one other class", "Substitutability is only relevant to method overloading, never to overriding"]'::jsonb, 0, 'oop', 'medium', true),
('A ''Square extends Rectangle'' design commonly fails the Liskov Substitution Principle because:', '["Setting a Square''s width and height independently, as Rectangle allows, would violate the Square''s invariant that all sides remain equal", "Squares cannot have their area calculated using the same formula as rectangles", "Most languages do not allow inheritance between geometric shape classes", "Rectangle must always be declared as an abstract class"]'::jsonb, 0, 'oop', 'medium', true),
('Which check would best help identify a class suffering from low cohesion during a code review?', '["Checking whether the class''s methods operate on a common, overlapping set of the class''s own fields", "Counting the total number of public methods, regardless of how they relate to each other", "Measuring only the number of libraries the class imports", "Checking whether the class name is short"]'::jsonb, 0, 'oop', 'medium', true),
('In the context of coupling, what does the ''law of Demeter'' (principle of least knowledge) generally advise?', '["An object should only communicate with its immediate collaborators and avoid reaching through them to access their internal objects", "An object should communicate directly with every other object in the system", "Objects should never have any collaborators at all", "Every method must call at least three other objects'' methods"]'::jsonb, 0, 'oop', 'medium', true),
('Which design generally results in lower coupling: depending on a concrete class, or depending on an interface or abstract type?', '["Depending on an interface or abstract type generally results in lower coupling, since implementations can vary without affecting the dependent class", "Depending on a concrete class always results in lower coupling", "Both approaches result in identical coupling in every language", "Coupling is unrelated to whether a dependency is concrete or abstract"]'::jsonb, 0, 'oop', 'medium', true),
('Which best explains why ''favor composition over inheritance'' does not mean ''never use inheritance''?', '["Inheritance remains appropriate when a genuine, stable ''is-a'' relationship exists and polymorphic substitutability is required, whereas composition is favored to avoid fragile hierarchies used solely for code reuse", "Inheritance should be used only for classes marked private", "Composition is strictly forbidden whenever interfaces are present in a design", "Inheritance is always faster at runtime than composition, which alone justifies its use"]'::jsonb, 0, 'oop', 'hard', true),
('The ''fragile base class problem'' refers to:', '["A situation where seemingly safe modifications to a base class, such as adding a new method, can unintentionally break derived classes relying on the base class''s exact prior behavior", "A base class that has no constructor defined at all", "A base class that fails to compile due to syntax errors", "A scenario where a derived class simply has more methods than its base class"]'::jsonb, 0, 'oop', 'hard', true),
('Which combination best represents an ideal module design according to the cohesion and coupling principle?', '["High cohesion within each module paired with low coupling between modules", "Low cohesion within each module paired with high coupling between modules", "High cohesion within each module paired with high coupling between modules", "Cohesion and coupling have no real bearing on module design quality"]'::jsonb, 0, 'oop', 'hard', true),
('A deep inheritance hierarchy, such as one with six or more levels, is often discouraged primarily because:', '["It increases the difficulty of understanding, tracing, and safely modifying behavior, since changes at any level can ripple unpredictably through many descendant classes", "Most compilers reject any hierarchy deeper than three levels", "It always causes a runtime stack overflow error", "Deep hierarchies eliminate the possibility of polymorphism entirely"]'::jsonb, 0, 'oop', 'hard', true),
('Which best captures why ''has-a'' composition relationships are often easier to test in isolation than ''is-a'' inheritance relationships?', '["A composed dependency can be replaced with a mock or stub implementing the same interface, whereas testing a subclass often also exercises inherited superclass behavior", "Composition relationships cannot be tested at all in any framework", "Inheritance relationships never require any superclass code to execute during testing", "Testing frameworks only support composition-based designs, never inheritance-based ones"]'::jsonb, 0, 'oop', 'hard', true);
INSERT INTO question_bank (question_text, options, correct_option, topic, difficulty, is_active) VALUES
('What does the ''S'' in SOLID stand for?', '["Single Responsibility Principle", "Static Resolution Principle", "Structural Reuse Principle", "Standard Response Principle"]'::jsonb, 0, 'oop', 'easy', true),
('What does the ''O'' in SOLID stand for?', '["Open/Closed Principle", "Object Orientation Principle", "Overload/Override Principle", "Optional Dependency Principle"]'::jsonb, 0, 'oop', 'easy', true),
('What does the ''L'' in SOLID stand for?', '["Liskov Substitution Principle", "Layered System Principle", "Loose Coupling Principle", "Late-binding Substitution Principle"]'::jsonb, 0, 'oop', 'easy', true),
('What does the ''I'' in SOLID stand for?', '["Interface Segregation Principle", "Inheritance Isolation Principle", "Immutable State Principle", "Instance Independence Principle"]'::jsonb, 0, 'oop', 'easy', true),
('What does the ''D'' in SOLID stand for?', '["Dependency Inversion Principle", "Data Integrity Principle", "Direct Instantiation Principle", "Design Interface Principle"]'::jsonb, 0, 'oop', 'easy', true),
('The Single Responsibility Principle states that:', '["A class should have only one reason to change", "A class should implement only one interface", "A class should have exactly one public method", "A class should be instantiated only once during a program''s execution"]'::jsonb, 0, 'oop', 'easy', true),
('The Open/Closed Principle states that software entities should be:', '["Open for extension but closed for modification", "Closed for extension but open for modification", "Open for both extension and modification at all times", "Closed for both extension and modification"]'::jsonb, 0, 'oop', 'easy', true),
('The Liskov Substitution Principle is primarily concerned with:', '["Ensuring subtypes can replace their base types without breaking the correctness of the program", "Ensuring every class has a single, well-defined responsibility", "Ensuring interfaces are kept small and narrowly focused", "Ensuring high-level modules depend directly on low-level modules"]'::jsonb, 0, 'oop', 'easy', true),
('The Interface Segregation Principle suggests that:', '["Clients should not be forced to depend on interfaces (methods) they do not use", "All classes should implement every interface available in a system", "Interfaces should always contain as many methods as possible", "Interfaces should never be used, in favor of abstract classes"]'::jsonb, 0, 'oop', 'easy', true),
('The Dependency Inversion Principle suggests that:', '["High-level modules should depend on abstractions, not on low-level concrete implementations", "Low-level modules should depend directly on high-level modules", "All dependencies should be hardcoded for the sake of performance", "Abstractions should depend on concrete implementation details"]'::jsonb, 0, 'oop', 'easy', true),
('A class that handles both business logic and directly manages database persistence violates which SOLID principle most directly?', '["Single Responsibility Principle", "Liskov Substitution Principle", "Interface Segregation Principle", "Dependency Inversion Principle"]'::jsonb, 0, 'oop', 'medium', true),
('Adding a new payment method to an e-commerce system by creating a new subclass of a PaymentMethod abstraction, without modifying any existing payment classes, exemplifies:', '["The Open/Closed Principle", "The Single Responsibility Principle", "The Interface Segregation Principle", "The Liskov Substitution Principle"]'::jsonb, 0, 'oop', 'medium', true),
('A fat interface with fifteen methods forces every implementing class to define methods it does not actually need. This is a violation of:', '["The Interface Segregation Principle", "The Open/Closed Principle", "The Dependency Inversion Principle", "The Single Responsibility Principle"]'::jsonb, 0, 'oop', 'medium', true),
('A high-level OrderService class directly instantiates a concrete MySQLDatabase class instead of depending on a DatabaseInterface abstraction. This violates:', '["The Dependency Inversion Principle", "The Liskov Substitution Principle", "The Single Responsibility Principle", "The Open/Closed Principle"]'::jsonb, 0, 'oop', 'medium', true),
('A subclass overrides a method and throws an exception for a case the superclass''s documented contract says should be handled normally. This is a classic violation of:', '["The Liskov Substitution Principle", "The Interface Segregation Principle", "The Open/Closed Principle", "The Single Responsibility Principle"]'::jsonb, 0, 'oop', 'medium', true),
('Which technique is commonly used to satisfy the Dependency Inversion Principle in practice?', '["Injecting an interface-typed dependency into a class, such as via constructor injection, rather than instantiating a concrete class internally", "Hardcoding all dependencies as static fields", "Removing all interfaces from the codebase entirely", "Relying only on global variables for shared state"]'::jsonb, 0, 'oop', 'medium', true),
('Splitting one large interface, such as ''Worker'' with eat(), sleep(), and work(), into smaller, role-specific interfaces primarily satisfies:', '["The Interface Segregation Principle", "The Liskov Substitution Principle", "The Single Responsibility Principle applied to interfaces only", "The Dependency Inversion Principle"]'::jsonb, 0, 'oop', 'medium', true),
('Which of the following best describes a class that is ''closed for modification'' under the Open/Closed Principle?', '["Its existing, already-tested source code does not need to be edited to add new behavior; new behavior is added through extension points such as subclassing or composition", "The class file is marked read-only by the operating system", "The class can never be compiled again after it is first written", "The class has no public methods at all"]'::jsonb, 0, 'oop', 'medium', true),
('Why does violating the Liskov Substitution Principle often break polymorphism-based code?', '["Client code written to work with the base type may receive unexpected behavior or errors when an LSP-violating subtype is substituted in, defeating the purpose of programming to an abstraction", "It only affects performance and never affects correctness", "It prevents the program from compiling in every language", "LSP violations only matter for private methods, never public ones"]'::jsonb, 0, 'oop', 'medium', true),
('A class implements an interface but leaves several of its methods with empty or ''not supported'' bodies just to satisfy the interface''s contract. This is typically a sign of:', '["An Interface Segregation Principle violation, because the interface is too broad for this class''s actual needs", "Proper use of the Single Responsibility Principle", "Correct application of the Open/Closed Principle", "A necessary and harmless OOP pattern with no real design concerns"]'::jsonb, 0, 'oop', 'medium', true),
('Which scenario best illustrates satisfying the Open/Closed Principle using a Strategy-style design?', '["Defining a common interface for algorithms and adding new algorithm classes that implement it, without modifying the class that uses the strategy", "Adding new ''if'' branches to an existing method every time a new case appears", "Editing the base class''s method body directly for each new requirement", "Removing the interface and hardcoding all logic into a single class"]'::jsonb, 0, 'oop', 'hard', true),
('How does Dependency Inversion relate to, but differ from, Dependency Injection?', '["Dependency Inversion is the design principle of depending on abstractions rather than concretions; Dependency Injection is one common technique used to achieve it by supplying dependencies from outside a class", "They are exactly the same concept, with no distinction whatsoever", "Dependency Injection is the underlying principle, and Dependency Inversion is merely the implementation technique", "Dependency Inversion applies only to database access code"]'::jsonb, 0, 'oop', 'hard', true),
('A subclass strengthens a method''s precondition (demanding stricter input than the superclass required) or weakens its postcondition (guaranteeing less than the superclass promised). According to the Liskov Substitution Principle, this is:', '["A violation, because valid superclass behavior expectations, such as weak preconditions and strong postconditions, must be preserved or improved by subclasses, not restricted", "Perfectly acceptable and actively encouraged in every case", "Irrelevant to the Liskov Substitution Principle, which only concerns method names", "Only a concern for abstract classes, never for concrete subclasses"]'::jsonb, 0, 'oop', 'hard', true),
('Which design smell most directly indicates a Single Responsibility Principle violation?', '["A class changes for multiple unrelated reasons, such as when both a business-rule change and a reporting-format change require editing the same class", "A class has too many private fields", "A class implements exactly one interface", "A class has only a single public constructor"]'::jsonb, 0, 'oop', 'hard', true),
('Why is ''programming to an interface, not an implementation'' considered foundational to both the Open/Closed and Dependency Inversion Principles?', '["Depending on stable abstractions rather than concrete details allows new implementations to be introduced or swapped without modifying dependent code, satisfying both extension-without-modification and high-level/low-level decoupling", "Because interfaces always execute faster than concrete classes at runtime", "Because implementations cannot be tested unless all interfaces are removed", "Because these principles apply only to statically typed languages"]'::jsonb, 0, 'oop', 'hard', true);
INSERT INTO question_bank (question_text, options, correct_option, topic, difficulty, is_active) VALUES
('Which access modifier makes a class member accessible from any other class, regardless of package or module?', '["public", "private", "protected", "default (package-private)"]'::jsonb, 0, 'oop', 'easy', true),
('In Java, what is the default access level of a class member when no access modifier is specified?', '["Package-private, accessible only within the same package", "Public, accessible from anywhere", "Private, accessible only within the declaring class", "Protected, accessible in subclasses across all packages"]'::jsonb, 0, 'oop', 'easy', true),
('Which access modifier is most appropriate for a field that should support encapsulation by preventing direct external access?', '["private", "public", "protected", "final"]'::jsonb, 0, 'oop', 'easy', true),
('What is ''static binding'' (also called early binding)?', '["The resolution of which method to call at compile time, based on the reference''s declared type", "The resolution of which method to call at runtime, based on the object''s actual type", "A binding that applies only to static variables and never to methods", "A process that occurs only after the program has finished executing"]'::jsonb, 0, 'oop', 'easy', true),
('What is ''dynamic binding'' (also called late binding)?', '["The resolution of which method implementation to call at runtime, based on the object''s actual type", "The resolution of which method to call at compile time, based on the reference''s declared type", "A binding used exclusively for static methods", "A binding that never changes once a program starts executing"]'::jsonb, 0, 'oop', 'easy', true),
('Which type of method call typically uses dynamic binding in languages like Java?', '["Overridden instance (virtual) method calls", "Static method calls", "Private method calls", "Calls to methods declared final"]'::jsonb, 0, 'oop', 'easy', true),
('Which type of method call typically uses static binding?', '["Overloaded method calls, resolved by matching parameter types at compile time", "Overridden virtual method calls made through a polymorphic reference", "Calls made purely through runtime reflection", "Calls to abstract methods implemented differently by each subclass"]'::jsonb, 0, 'oop', 'easy', true),
('The keyword ''final'' applied to a method in Java indicates that:', '["The method cannot be overridden by any subclass", "The method can only be called once during the entire program execution", "The method must also be declared static", "The method automatically becomes private"]'::jsonb, 0, 'oop', 'easy', true),
('Which of the following are typically resolved using static binding because they cannot be overridden polymorphically?', '["Static methods and private methods", "Public virtual instance methods", "Abstract methods implemented differently in each subclass", "Interface default methods"]'::jsonb, 0, 'oop', 'easy', true),
('What does it mean for a variable or field to be declared ''final'' in Java?', '["Its value or reference cannot be reassigned once it has been initialized", "It can only be accessed from within static methods", "It automatically becomes a public member", "It must be declared using an abstract type"]'::jsonb, 0, 'oop', 'easy', true),
('Class A defines method print(), and class B extends A without overriding print(). If B b = new B(); b.print(); is called, which version executes?', '["A''s version of print(), since B inherits it unchanged", "A compiler error occurs because B lacks its own print() method", "No version executes; the call is silently ignored", "Both A''s and B''s versions execute together"]'::jsonb, 0, 'oop', 'medium', true),
('A method is declared ''private'' in a superclass. If a subclass defines a method with the exact same name and signature, what actually happens?', '["The subclass method is an entirely new, independent method, not an override, since private methods are not inherited or visible for overriding", "It automatically overrides the superclass''s private method", "It causes a compilation error due to a duplicate method name", "It silently merges with the superclass''s method into a single method"]'::jsonb, 0, 'oop', 'medium', true),
('Why do overloaded methods use static binding rather than dynamic binding?', '["The compiler can unambiguously determine which overload to call just by examining the argument types at compile time, without needing runtime object information", "Because overloaded methods are always declared private", "Because method overloading is not supported by any compiled language", "Because dynamic binding is reserved exclusively for constructors"]'::jsonb, 0, 'oop', 'medium', true),
('Which scenario most clearly demonstrates the difference between static and dynamic binding?', '["Animal a = new Dog(); a.makeSound(); calls Dog''s overridden makeSound() at runtime, even though ''a'' is declared with the static type Animal", "int x = 5; int y = x + 2; demonstrates dynamic binding", "Calling a static utility method always demonstrates dynamic binding", "Declaring a private field demonstrates dynamic binding"]'::jsonb, 0, 'oop', 'medium', true),
('In C++, why must a base class method be declared ''virtual'' for dynamic binding (runtime polymorphism) to occur through a base class pointer?', '["By default, C++ resolves method calls using static binding; the ''virtual'' keyword instructs the compiler to use a runtime dispatch mechanism, such as a vtable, instead", "Because all C++ methods use dynamic binding automatically without any keyword needed", "Because ''virtual'' converts the method into a static method", "Because C++ does not support polymorphism under any circumstance"]'::jsonb, 0, 'oop', 'medium', true),
('Which of the following would generally be resolved via static binding, even in a language that supports dynamic dispatch for instance methods?', '["A call to a constructor", "A call to an overridden virtual method made through a base class reference", "A call routed through an interface reference to different implementing classes", "A call to an abstract method implemented differently by each subclass"]'::jsonb, 0, 'oop', 'medium', true),
('Marking a class as ''final'' in Java has what effect related to inheritance?', '["It prevents any subclassing of that class", "It forces every method in the class to become abstract", "It automatically makes every field in the class public", "It has no effect on inheritance whatsoever"]'::jsonb, 0, 'oop', 'medium', true),
('Which statement about access modifiers and inheritance is correct?', '["A protected member is accessible within the declaring class, its subclasses, and often other classes in the same package, but not by unrelated external classes", "A protected member is accessible from absolutely anywhere in the program", "A protected member has visibility identical to that of a private member", "A protected member can never be accessed by the declaring class''s own subclasses"]'::jsonb, 0, 'oop', 'medium', true),
('Why might a language designer choose to make fields private and expose behavior through public methods rather than making fields protected for subclass access?', '["To preserve encapsulation and control over invariants, since protected fields can be directly modified by any subclass, potentially breaking the class''s internal consistency", "Because protected fields are not supported by any compiler", "Because private fields run measurably faster than protected fields", "Because protected access always causes memory leaks"]'::jsonb, 0, 'oop', 'medium', true),
('Why did interfaces traditionally allow only ''public abstract'' methods, before default methods were introduced?', '["Since an interface defines a contract meant to be fully implemented by any implementing class, its methods needed to be public and lack implementation, making them implicitly abstract", "Because private methods were technologically impossible to compile at the time", "Because interfaces originally could not declare any methods at all", "Because ''public'' was required solely to enable static binding"]'::jsonb, 0, 'oop', 'medium', true),
('Consider: class A defines void show() that prints "A"; class B extends A and overrides show() to print "B", and also defines an overloaded show(int x) that prints "Bx". Given A ref = new B(); ref.show(); what is printed, and why?', '["\"B\" is printed, because show() is an overridden instance method resolved via dynamic binding based on the actual object type (B), regardless of the reference''s declared type (A)", "\"A\" is printed, because the reference''s declared type A determines which show() runs", "\"Bx\" is printed, because B also defines an overloaded version", "A compile-time error occurs due to ambiguous method resolution"]'::jsonb, 0, 'oop', 'hard', true),
('Why does field access, unlike overridden instance method access, in Java use static binding even through a polymorphic reference?', '["Fields are not polymorphic in Java; they are resolved based on the declared (static) type of the reference at compile time, unlike overridden methods, which use the runtime type", "Because fields cannot be inherited by subclasses at all", "Because fields always use dynamic binding, exactly like methods", "Because Java does not allow a subclass field to shadow a superclass field"]'::jsonb, 0, 'oop', 'hard', true),
('A subclass ''shadows'' (redeclares) a field with the same name as one in its superclass. Given A ref = new B(); where B shadows field x, what does ref.x access?', '["A''s version of the field x, since field access is statically bound to the reference''s declared type, not the runtime object type", "B''s version of the field x, since fields use dynamic binding just like methods", "A compilation error, since shadowing fields is illegal in Java", "Both fields simultaneously, merged into a single value"]'::jsonb, 0, 'oop', 'hard', true),
('Why do languages typically disallow overriding a static method as though it were an instance method, instead treating same-signature static methods in a subclass as ''hiding'' the superclass version?', '["Static methods belong to the class itself, not to object instances, so there is no object-based runtime dispatch mechanism, such as a vtable, to select between versions polymorphically", "Because static methods cannot share the same name as any other method in a program", "Because static methods are actually private by default in every language", "Because hiding and overriding are technically identical concepts in every language"]'::jsonb, 0, 'oop', 'hard', true),
('In C++, if a virtual function is called from within a base class constructor, why does it NOT invoke the derived class''s override, even though the actual runtime object is of the derived type?', '["During base class construction, the object''s virtual dispatch mechanism still reflects the base class, since the derived part of the object has not yet been constructed, so the call resolves to the base class''s version", "Because C++ constructors always use full dynamic binding, identical to how Java behaves in this situation", "Because virtual functions cannot legally be called from any constructor, which causes a compile error", "Because the derived class object does not exist in memory at all until after its constructor finishes"]'::jsonb, 0, 'oop', 'hard', true);
INSERT INTO question_bank (question_text, options, correct_option, topic, difficulty, is_active) VALUES
('What is the primary intent of the Singleton design pattern?', '["To ensure a class has only one instance and to provide a global point of access to it", "To create multiple instances of a class efficiently", "To allow a class to inherit from multiple parent classes", "To hide a class''s constructor from every caller, including the class itself"]'::jsonb, 0, 'oop', 'easy', true),
('Which design pattern is commonly used to create objects without specifying the exact class of object that will be created?', '["Factory pattern", "Singleton pattern", "Observer pattern", "Composite pattern"]'::jsonb, 0, 'oop', 'easy', true),
('The Observer design pattern is primarily used to:', '["Define a one-to-many dependency so that when one object (the subject) changes state, all its dependents (observers) are notified automatically", "Ensure that only one instance of a class exists throughout an application", "Create objects without exposing the underlying instantiation logic", "Convert the interface of a class into another interface clients expect"]'::jsonb, 0, 'oop', 'easy', true),
('In the Singleton pattern, how is uncontrolled instantiation typically prevented?', '["By making the constructor private and providing a static method to access the single shared instance", "By making the constructor public and simply documenting a rule not to call it twice", "By deleting the class definition after the first object is created", "By declaring the class as an interface"]'::jsonb, 0, 'oop', 'easy', true),
('Which term describes the objects that register interest in and receive notifications from a ''subject'' in the Observer pattern?', '["Observers (or subscribers/listeners)", "Factories", "Singletons", "Adapters"]'::jsonb, 0, 'oop', 'easy', true),
('Which of the following is a real-world analogy commonly used to explain the Observer pattern?', '["Subscribing to a newsletter, where subscribers are automatically notified whenever a new issue is published", "Building a car from standardized, interchangeable parts", "Ensuring only one president leads a country at a time", "Wrapping a gift so its contents are not directly visible"]'::jsonb, 0, 'oop', 'easy', true),
('The Factory pattern helps decouple client code from:', '["The concrete classes it needs to instantiate", "The interfaces it implements", "The private fields of unrelated classes", "The static methods defined in the client class itself"]'::jsonb, 0, 'oop', 'easy', true),
('Which of these is a common real-world use case for the Singleton pattern?', '["A single configuration manager or logging service shared across an entire application", "A new user account created for every login attempt", "A list that stores many unrelated data types", "A method that is overloaded based on argument count"]'::jsonb, 0, 'oop', 'easy', true),
('What term is used for the object being observed, whose state changes trigger notifications, in the Observer pattern?', '["Subject (or Observable)", "Listener", "Product", "Client"]'::jsonb, 0, 'oop', 'easy', true),
('Which of the following best describes a ''Factory Method'' pattern at a high level?', '["A creational pattern that defines an interface for creating an object, letting subclasses decide which concrete class to instantiate", "A structural pattern that adapts one interface to another", "A behavioral pattern that notifies multiple objects of state changes", "A pattern that restricts a class to producing only a single instance"]'::jsonb, 0, 'oop', 'easy', true),
('Which category of design patterns does the Singleton pattern belong to?', '["Creational", "Structural", "Behavioral", "Concurrent"]'::jsonb, 0, 'oop', 'medium', true),
('Which category of design patterns does the Observer pattern belong to?', '["Behavioral", "Creational", "Structural", "Architectural"]'::jsonb, 0, 'oop', 'medium', true),
('In a naive (non-thread-safe) Singleton implementation using lazy initialization, what problem can arise in a multithreaded environment?', '["Two threads could simultaneously pass the null-check before the instance is created, resulting in two separate instances being constructed, violating the Singleton guarantee", "The class will fail to compile in any multithreaded program", "The runtime will automatically prevent this problem by default in every language", "Multithreading has no effect whatsoever on Singleton implementations"]'::jsonb, 0, 'oop', 'medium', true),
('How does the ''double-checked locking'' technique attempt to fix thread-safety issues in lazy Singleton initialization?', '["By synchronizing only the block that creates the instance, and checking the null condition both before and after acquiring the lock, minimizing synchronization overhead once the instance exists", "By creating a brand-new instance on every single method call, regardless of locking", "By removing all synchronization entirely to maximize speed", "By making the class abstract to sidestep instantiation issues"]'::jsonb, 0, 'oop', 'medium', true),
('Why is the Singleton pattern sometimes criticized as an anti-pattern in software design?', '["It introduces global state and hidden dependencies, making unit testing harder and working against dependency injection best practices", "It always causes memory leaks in every programming language", "It cannot be implemented in any object-oriented language", "It requires multiple inheritance in order to function correctly"]'::jsonb, 0, 'oop', 'medium', true),
('In the Observer pattern, what is a key benefit regarding coupling between the subject and its observers?', '["The subject only needs to know that observers implement a common observer interface, not their concrete classes, allowing observers to be added or removed without modifying the subject", "The subject must know the exact concrete class of every observer it notifies", "Observers must know every detail of the subject''s private implementation", "The pattern requires tight coupling between subject and observers by design"]'::jsonb, 0, 'oop', 'medium', true),
('Which of the following is an example of the Factory pattern being used to promote the Open/Closed Principle?', '["Adding a new product type by creating a new class and extending the factory, without altering how client code requests objects", "Hardcoding ''new ConcreteClass()'' calls throughout client code for each product type", "Removing the factory entirely once the first product type has been added", "Requiring every client to know the internal fields of each product class"]'::jsonb, 0, 'oop', 'medium', true),
('What is the key structural difference between a Simple/Static Factory and the Abstract Factory pattern?', '["A Simple Factory typically creates one type of product via a single method, while an Abstract Factory provides an interface for creating families of related products", "There is no meaningful difference between the two patterns", "An Abstract Factory can only ever create exactly one object, unlike a Simple Factory", "A Simple Factory always requires multiple inheritance, unlike an Abstract Factory"]'::jsonb, 0, 'oop', 'medium', true),
('In a publish-subscribe (pub-sub) messaging system, which classic design pattern is this architecture most conceptually related to?', '["Observer pattern", "Singleton pattern", "Factory pattern", "Builder pattern"]'::jsonb, 0, 'oop', 'medium', true),
('Which statement about ''push'' versus ''pull'' models in the Observer pattern is accurate?', '["In the push model, the subject sends detailed state data directly in the notification; in the pull model, the subject only signals that a change occurred, and observers query the subject for details as needed", "Push and pull models are unrelated to the Observer pattern", "In the pull model, observers push data into the subject instead of querying it", "Push and pull describe two unrelated creational patterns"]'::jsonb, 0, 'oop', 'medium', true),
('Which approach to implementing a Singleton in Java is generally considered both thread-safe and lazy, without requiring explicit synchronization on every access?', '["The ''initialization-on-demand holder'' idiom, which relies on the JVM''s class-loading guarantees to lazily and safely initialize a static holder class''s instance", "Declaring the instance as a public, non-final static field with eager initialization only", "Using a plain, unsynchronized lazy getInstance() method that merely checks for null", "Creating a brand-new instance inside every method that needs it"]'::jsonb, 0, 'oop', 'hard', true),
('Why can Java enums be used to implement a Singleton safely, including protection against reflection-based instantiation attacks?', '["The JVM guarantees that each enum constant is instantiated exactly once, and reflection cannot invoke enum constructors to create additional instances, unlike ordinary classes with merely private constructors", "Because enums cannot have any methods, which forces single-instance behavior", "Because enums are automatically abstract and therefore cannot be referenced", "Because reflection is disabled entirely whenever an enum type is present in a program"]'::jsonb, 0, 'oop', 'hard', true),
('Which design consideration distinguishes the Factory Method pattern from the Abstract Factory pattern in terms of extensibility?', '["Factory Method relies on subclassing to vary the product created, while Abstract Factory relies on object composition, allowing entire families of related objects to be swapped by changing the concrete factory instance", "Factory Method cannot be extended once written, unlike Abstract Factory", "Abstract Factory always produces exactly one object type per class, exactly like Factory Method", "Both patterns are identical in every implementation detail"]'::jsonb, 0, 'oop', 'hard', true),
('In the Observer pattern, what potential issue can arise if an observer''s update() method itself triggers changes that cause the subject to notify observers again recursively?', '["It can lead to infinite notification loops or inconsistent state updates if not carefully guarded against, since the notification chain can re-enter itself", "This scenario is impossible in any correct Observer implementation", "The subject automatically detects and prevents all recursive notifications by default in every language", "This issue only affects the Singleton pattern, never the Observer pattern"]'::jsonb, 0, 'oop', 'hard', true),
('Why might combining the Singleton pattern with the Factory pattern (a ''Singleton Factory'') be a reasonable design choice in some systems?', '["To ensure a single, shared factory instance manages object creation logic consistently across the application, centralizing creation rules while avoiding redundant factory instances", "Because the two patterns can never coexist within the same system under any circumstances", "Because combining patterns is mandated by the Interface Segregation Principle", "Because Factory patterns must always be instantiated exactly once by definition, making Singleton redundant"]'::jsonb, 0, 'oop', 'hard', true);
INSERT INTO question_bank (question_text, options, correct_option, topic, difficulty, is_active) VALUES
('Which OOP concept is most closely associated with the phrase ''programming to an interface, not an implementation''?', '["Abstraction", "Destructor design", "Static binding", "Field shadowing"]'::jsonb, 0, 'oop', 'easy', true),
('A method shares the same name in both a superclass and a subclass but performs an unrelated task and has a different parameter list. This is an example of:', '["Overloading, not overriding, since the parameter signatures differ", "Overriding, since the method names match", "Encapsulation, since data is being hidden", "Composition, since one class contains another"]'::jsonb, 0, 'oop', 'easy', true),
('Which of the following is typically NOT a valid way to achieve abstraction in OOP?', '["Making all of a class''s fields public with no accompanying methods", "Using an abstract class with some unimplemented methods", "Using an interface to define a contract", "Hiding implementation details behind well-defined method signatures"]'::jsonb, 0, 'oop', 'easy', true),
('A UML class diagram shows the multiplicity ''1..*'' next to an association end. What does this indicate?', '["One or more instances of that class participate in the relationship", "Exactly one instance participates, no more and no less", "Zero instances ever participate in the relationship", "The relationship is optional and capped at exactly two instances"]'::jsonb, 0, 'oop', 'medium', true),
('In a UML class diagram, a ''+'' symbol before an attribute or method name typically denotes:', '["Public visibility", "Private visibility", "Protected visibility", "Package (default) visibility"]'::jsonb, 0, 'oop', 'medium', true),
('In a UML class diagram, a ''-'' symbol before an attribute or method name typically denotes:', '["Private visibility", "Public visibility", "Protected visibility", "Static scope"]'::jsonb, 0, 'oop', 'medium', true),
('A UML class diagram uses a ''#'' symbol before a member name. What visibility does this represent, and how does it relate to inheritance-based access?', '["Protected visibility; the member is accessible within the class and its subclasses (and often the same package), aligning with controlled inheritance-based access", "Package visibility, which is unrelated to inheritance in any way", "Public visibility, accessible from any unrelated class", "Private visibility, inaccessible even to the class''s own subclasses"]'::jsonb, 0, 'oop', 'hard', true),
('Why does combining small, focused interfaces for contracts with an abstract base class for shared default logic help balance the Interface Segregation Principle and code-reuse concerns at the same time?', '["Interfaces keep contracts small and focused, supporting the Interface Segregation Principle, while an abstract base class can implement shared boilerplate for classes that opt into it, so reuse does not force unrelated classes into one rigid hierarchy or into fat interfaces", "Because interfaces and abstract classes are functionally identical, so combining them changes nothing", "Because abstract classes eliminate the need for any interface within the same hierarchy", "Because this combination is disallowed in all major object-oriented languages"]'::jsonb, 0, 'oop', 'hard', true);
